WITH daily_returns AS (SELECT wp.wp_web_page_id, d.d_date, SUM(wr.wr_return_amt) AS daily_return_amt FROM web_page wp JOIN web_returns wr ON wr.wr_web_page_sk = wp.wp_web_page_sk JOIN date_dim d ON wr.wr_returned_date_sk = d.d_date_sk GROUP BY wp.wp_web_page_id, d.d_date) SELECT dr.wp_web_page_id, dr.d_date, dr.daily_return_amt, AVG(dr.daily_return_amt) OVER (PARTITION BY dr.wp_web_page_id ORDER BY dr.d_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7d, CASE WHEN dr.daily_return_amt > 1000 THEN 'High' ELSE 'Normal' END AS return_level, RANK() OVER (PARTITION BY dr.wp_web_page_id ORDER BY dr.daily_return_amt DESC) AS daily_return_rank FROM daily_returns dr ORDER BY dr.wp_web_page_id, dr.d_date
